Workflow.Definition:
"@@ConnectionString: ''
@@Type: 'Local'
@@DesktopType: 'local'
@@DisplayName: 'Local computer'
IMPORT 'controlRepo.appmask' AS appmask
IMPORT 'imageRepo.imgrepo' AS imgrepo
@SENSITIVE: []
@INPUT InputUserUdn : { 'Description': '', 'FriendlyName': 'InputUserUdn', 'DefaultValue': '', 'Type': 'String' } 
@INPUT InputGroupID : { 'Description': '', 'FriendlyName': 'InputGroupID', 'DefaultValue': '', 'Type': 'String' } 
LABEL 'Run from \"Call Add User to group\"'
ActiveDirectory.ConnectToServer.ConnectToServerWithAuthentication LdapPath: $'''LDAP://S-DC1.smkb.ac.il''' Username: $'''''' Password: P'' AuthenticationType: ActiveDirectory.AuthenticationTypes.Secure ParentDirectoryEntry=> ParentDirectoryEntry
ActiveDirectory.ModifyGroup.AddUserToGroup ParentDirectoryEntry: ParentDirectoryEntry DistinguishedName: InputGroupID UserDistinguishedName: InputUserUdn
ActiveDirectory.CloseConnection ParentDirectoryEntry: ParentDirectoryEntry
"
